"""Stage 4 — `./tasks.ps1 synth` / `make synth` / `python -m pratirakshak.synth [--skip-train]`."""

from __future__ import annotations

import argparse
import sys

from pratirakshak.io import read_json, write_text
from pratirakshak.settings import REPORTS_DIR
from pratirakshak.synth import anchor_hydraulic


def report(results: list[dict], anchor: dict | None) -> str:  # type: ignore[type-arg]
    L = ["# Non-engine systems — estimate vs synthetic truth  `SIMULATED`", "",
         "_Generated by `python -m pratirakshak.synth`. These systems are synthetic (SPEC §7.1); errors are measured "
         "against the generator's own ground truth on held-out synthetic airframes (60/20/20 split by airframe). "
         "RUL capped at 150 days. Not real fleet data._", "",
         "| System | Failures simulated | Test rows | RMSE (days) | MAE (days) | MAE when RUL ≤ 30 d | PICP 80 % | MPIW 80 % (days) |",
         "|---|---|---|---|---|---|---|---|"]
    for r in results:
        L.append(f"| {r['system']} | {r['failures_observed']} | {r['rows_test']:,} | {r['rmse_days']:.2f} | {r['mae_days']:.2f} | "
                 f"{r['mae_days_when_rul_le_30']} | {r['picp80']:.3f} | {r['mpiw80_days']:.1f} |")
    L += ["", "Structure fails rarely within the simulated span (long design life), so most of its test rows sit at the "
          "150-day cap and its low MAE mostly reflects that, not skill at predicting structural failure.", "",
          "## Hydraulics real anchor  `REAL-ANCHORED`", ""]
    if anchor is None:
        L.append("UCI hydraulic data not present: hydraulics sensors use configured ranges (SIMULATED).")
    else:
        v, c = anchor["validation"], anchor["calibration"]
        L += [f"Source: {anchor['source']}. {anchor['cycles']} real load cycles. Split: {v['split']} "
              f"(train {v['n_train']}, test {v['n_test']}).", "",
              "| Real target | Accuracy | Macro-F1 |", "|---|---|---|"]
        L += [f"| {t} | {m['accuracy']:.3f} | {m['macro_f1']:.3f} |" for t, m in v["targets"].items()]
        L += ["", "Calibration taken into the synthetic hydraulics sensors (severe rig state ≙ damage 0.8):", "",
              f"- pressure: relative cycle-to-cycle noise {c['pressure_rel_noise']:.2e}; severe internal pump leak changes "
              f"mean pressure by {c['pressure_rel_change_severe_leak']:+.2%}",
              f"- fluid temperature: cooler near-failure raises it by {c['temperature_rise_cooler_failure_c']:.1f} °C "
              f"(noise {c['temperature_noise_c']:.3f} °C)",
              f"- flow: relative noise {c['flow_rel_noise']:.2e}; severe leak changes flow by {c['flow_rel_change_severe_leak']:+.2%}",
              "- The rig is laboratory-grade, so configured in-flight noise is used as a floor."]
    return "\n".join(L) + "\n"


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--skip-train", action="store_true", help="reuse trained system models")
    args = ap.parse_args()

    anchor = anchor_hydraulic.run() if anchor_hydraulic.available() else anchor_hydraulic.load_anchor()
    print("hydraulics anchor:", "UCI data (fresh)" if anchor_hydraulic.available() else
          ("committed anchor json" if anchor else "none → configured ranges"))

    from pratirakshak.synth.fleet import build_d0
    from pratirakshak.synth.model import SYSTEMS
    from pratirakshak.synth.train import OUT, train_all

    if args.skip_train:
        results = [read_json(OUT / s / "metrics.json") for s in SYSTEMS]
    else:
        print("training non-engine system models on synthetic airframes …")
        results = train_all()
    write_text(REPORTS_DIR / "system_models.md", report(results, anchor))

    print("building fleet state at D+0 …")
    st = build_d0()
    ac = st["aircraft"]
    print("\nStatus by base (D+0):")
    print(ac.pivot_table(index="base", columns="status", values="tail", aggfunc="count", fill_value=0).to_string())
    print("\nLimiting systems:", ac["limiting_system"].value_counts().to_dict())
    print(f"Weighted health: mean {ac['weighted_health'].mean():.1f}, min {ac['weighted_health'].min():.1f}; "
          f"sensor-history rows {st['history_rows']:,}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
